    f = []
    for k in range(1, 1001):
        g.append((1/(k+1))**(1/k))
        f.append((1/k)**(1/k))

    max_n = 0
    endpoints = []
    for k in range(1000):
        endpoints.append(g[k])
        endpoints.append(f[k])
    endpoints.sort()

    for x in endpoints:
        # Try x and x + epsilon
        for eps in [0, 1e-9]:
            val = x + eps
